import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Card, Typography, Switch, Button, Space, Row, Col, Input, Tooltip, Divider, message, InputNumber, List, Tag, Select } from "antd";
import { FileText as FileTextIcon, RefreshCw as RefreshIcon, Settings as SettingsIcon } from "lucide-react";
import { apiRequest } from "../api";

const { Title, Text } = Typography;

type LogsResponse = {
  unit: string;
  lines: number;
  filter: string;
  text: string;
};

const MONO_STYLE: React.CSSProperties = {
  fontFamily: "ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, 'Liberation Mono', 'Courier New', monospace",
  fontSize: 12,
  whiteSpace: "pre-wrap",
  background: "#0f172a",
  color: "#e2e8f0",
  padding: 12,
  borderRadius: 8,
  minHeight: 220,
  maxHeight: 360,
  overflowY: "auto",
  border: "1px solid rgba(148,163,184,.25)",
};

type AuditItem = {
  event_type?: string;
  description?: string;
  ts?: string;
  meta?: any;
  quant_id?: string | null;
};

export default function SoulLogs() {
  const [enabled, setEnabled] = useState<boolean>(() => localStorage.getItem("soul_logs_enabled") === "1");
  const [filter, setFilter] = useState<string>(() => localStorage.getItem("soul_logs_filter") || "SOUL");
  const [lines, setLines] = useState<number>(() => {
    const v = Number(localStorage.getItem("soul_logs_lines") || 800);
    return isFinite(v) && v > 0 ? v : 800;
  });
  const [logsSoul, setLogsSoul] = useState<string>("");
  const [logsAll, setLogsAll] = useState<string>("");
  const [loading, setLoading] = useState<boolean>(false);
  const [audit, setAudit] = useState<AuditItem[]>([]);
  const [auditLimit, setAuditLimit] = useState<number>(50);
  const [source, setSource] = useState<'backend'|'nginx_access'|'nginx_error'>(() => (localStorage.getItem('soul_logs_source') as any) || 'backend');
  const soulBoxRef = useRef<HTMLDivElement | null>(null);
  const allBoxRef = useRef<HTMLDivElement | null>(null);

  const fetchLogs = useCallback(async () => {
    try {
      setLoading(true);
      // Кванты/Соул (фильтр по подстроке)
      const dataSoul = source === 'backend'
        ? await apiRequest(`/admin/soul/logs?filter=${encodeURIComponent(filter)}&lines=${lines}`, "GET")
        : await apiRequest(`/admin/soul/logs/nginx?kind=${source==='nginx_access'?'access':'error'}&lines=${lines}&filter=${encodeURIComponent(filter)}`, "GET");
      setLogsSoul((dataSoul as LogsResponse)?.text || "");
      // Полный лог (без фильтра)
      const dataAll = await apiRequest(`/admin/soul/logs?filter=&lines=${lines}`, "GET");
      setLogsAll((dataAll as LogsResponse)?.text || "");
      // Аудит
      try {
        const dataAudit: any = await apiRequest(`/admin/soul/audit/recent?limit=${auditLimit}`, "GET");
        setAudit(Array.isArray(dataAudit?.items) ? dataAudit.items : []);
      } catch (e) {
        // не блокируем
      }
      // автопрокрутка в конец
      setTimeout(() => {
        soulBoxRef.current?.scrollTo({ top: soulBoxRef.current.scrollHeight });
        allBoxRef.current?.scrollTo({ top: allBoxRef.current.scrollHeight });
      }, 0);
    } catch (e) {
      message.error("Ошибка загрузки логов");
    } finally {
      setLoading(false);
    }
  }, [filter, lines, auditLimit, source]);

  useEffect(() => {
    if (!enabled) return;
    fetchLogs();
    const t = setInterval(fetchLogs, 5000);
    return () => clearInterval(t);
  }, [enabled, fetchLogs]);

  const downloadUrlSoul = useMemo(() => `/api/admin/soul/logs/download?filter=${encodeURIComponent(filter)}&lines=${lines}`, [filter, lines]);
  const downloadUrlAll = useMemo(() => `/api/admin/soul/logs/download?filter=&lines=${lines}`, [lines]);

  const onToggle = (val: boolean) => {
    setEnabled(val);
    localStorage.setItem("soul_logs_enabled", val ? "1" : "0");
    if (val) fetchLogs();
  };

  return (
    <div style={{ padding: 24 }}>
      <Space direction="vertical" size={16} style={{ width: "100%" }}>
        <div>
          <Title level={2} style={{ marginBottom: 0 }}>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
              <img src="/android-chrome-192x192.png" alt="Soul" style={{ width: 28, height: 28, borderRadius: 6 }} />
              Соул · Логи
            </span>
          </Title>
          <Text type="secondary">Онлайн‑просмотр серверных логов (unit: soulpulse-backend.service) и событий аудита</Text>
        </div>

        <Card>
          <Space align="center" wrap>
            <Switch checked={enabled} onChange={onToggle} />
            <Text>Включить логи — Кванты</Text>
            <Divider type="vertical" />
            <Tooltip title="Подстрока для фильтрации (например, SOUL, [SOUL-RES])">
              <Input
                style={{ width: 220 }}
                placeholder="Фильтр подстроки"
                value={filter}
                onChange={(e) => { setFilter(e.target.value); localStorage.setItem("soul_logs_filter", e.target.value); }}
              />
            </Tooltip>
            <Select
              value={source}
              onChange={(v)=> { setSource(v as any); localStorage.setItem('soul_logs_source', String(v)); setTimeout(fetchLogs, 0); }}
              style={{ width: 220 }}
              options={[
                { value: 'backend', label: 'Backend (journalctl)' },
                { value: 'nginx_access', label: 'Nginx access.log' },
                { value: 'nginx_error', label: 'Nginx error.log' },
              ]}
            />
            <Tooltip title="Количество последних строк">
              <InputNumber
                style={{ width: 140 }}
                min={50}
                max={5000}
                step={50}
                value={lines}
                onChange={(v) => { const n = Math.max(50, Math.min(5000, Number(v)||800)); setLines(n); localStorage.setItem("soul_logs_lines", String(n)); }}
              />
            </Tooltip>
            <Button icon={<RefreshIcon size={16} />} onClick={fetchLogs} loading={loading}>Обновить</Button>
            <Button icon={<SettingsIcon size={16} />} onClick={() => window.open('/soul/dashboard', '_self')}>К дашборду</Button>
            <Button onClick={() => { setLines(Math.min(5000, lines + 500)); setTimeout(fetchLogs, 0); }}>Показать ещё +500</Button>
          </Space>
        </Card>

        <Row gutter={[16, 16]}>
          <Col xs={24} lg={12}>
            <Card title={`Кванты / SOUL (фильтр: "${filter || '—'}")`} extra={<Button icon={<FileTextIcon size={16} />} onClick={() => window.open(downloadUrlSoul, '_blank')}>Открыть в редакторе</Button>}>
              <div ref={soulBoxRef} style={ MONO_STYLE }>
                {logsSoul || '—'}
              </div>
            </Card>
          </Col>
          <Col xs={24} lg={12}>
            <Card title="Полный лог сервиса" extra={<Button icon={<FileTextIcon size={16} />} onClick={() => window.open(downloadUrlAll, '_blank')}>Открыть в редакторе</Button>}>
              <div ref={allBoxRef} style={ MONO_STYLE }>
                {logsAll || '—'}
              </div>
            </Card>
          </Col>
        </Row>

        <Card title="События аудита (soul_audit_log)" extra={
          <Space>
            <span>limit:</span>
            <InputNumber min={10} max={500} step={10} value={auditLimit} onChange={(v) => { setAuditLimit(Number(v||50)); }} />
            <Button onClick={() => fetchLogs()} loading={loading}>Обновить</Button>
          </Space>
        }>
          <List
            dataSource={audit}
            renderItem={(it) => (
              <List.Item>
                <Space direction="vertical" size={2} style={{ width: '100%' }}>
                  <Space wrap>
                    <Tag>{it.event_type || 'event'}</Tag>
                    {it.quant_id && <Tag color="purple">{String(it.quant_id).slice(0,8)}…</Tag>}
                    <Text type="secondary">{it.ts ? new Date(it.ts).toLocaleString() : ''}</Text>
                  </Space>
                  {it.description && <Text>{it.description}</Text>}
                  {it.meta && (
                    <Tooltip title={<pre style={{ whiteSpace: 'pre-wrap' }}>{JSON.stringify(it.meta, null, 2)}</pre>}>
                      <Text type="secondary" style={{ cursor: 'pointer' }}>meta ▸</Text>
                    </Tooltip>
                  )}
                </Space>
              </List.Item>
            )}
          />
        </Card>
      </Space>
    </div>
  );
}
